package pe.com.dentalamericana.messaging;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import pe.com.dentalamericana.patient.*;import java.time.*;
@Service public class FollowUpService{private final PostConsultationFollowUpRepository followups;private final MessageOutboxService outbox;private final PatientService patients;public FollowUpService(PostConsultationFollowUpRepository f,MessageOutboxService o,PatientService p){followups=f;outbox=o;patients=p;}@Transactional public void schedule(Long patientId,Long encounterId,Long actor){Patient p=patients.find(patientId);Instant when=Instant.now().plus(24,java.time.temporal.ChronoUnit.HOURS);PostConsultationFollowUp f=followups.save(new PostConsultationFollowUp(patientId,encounterId,when,actor));WhatsAppMessage m=outbox.queueFollowUp(p,encounterId,when,actor);if(m!=null)f.attachMessage(m.getId());else f.closeWithoutMessage("SIN_AUTORIZACION_O_CELULAR");}}
